import json, re, chess
S = "1.d4 Nf6 2.c4 e6 3.Nc3 Bb4 4.e3 d5 5.a3 Bxc3+ 6.bxc3 c5 7.cxd5 exd5 8.Bd3 0-0 9.Ne2 b6 10.0-0 Ba6 11.Bxa6 Nxa6 12.Bb2 Qd7 13.a4 Rfe8 14.Qd3 c4 15.Qc2 Nb8 16.Rae1 Nc6 17.Ng3 Na5 18.f3 Nb3 19.e4 Qxa4 20.e5 Nd7 21.Qf2 g6 22.f4 f5 23.exf6 Nxf6 24.f5 Rxe1 25.Rxe1 Re8 26.Re6 Rxe6 27.fxe6 Kg7 28.Qf4 Qe8 29.Qe5 Qe7 30.Ba3 Qxa3 31.Nh5+ gxh5 32.Qg5+ Kf8 33.Qxf6+ Kg8 34.e7 Qc1+ 35.Kf2 Qc2+ 36.Kg3 Qd3+ 37.Kh4 Qe4+ 38.Kxh5 Qe2+ 39.Kh4 Qe4+ 40.g4 Qe1+ 41.Kh5"
b = chess.Board()
P = []
for t in S.split():
    t = re.sub(r'^\d+\.', '', t)
    if not t:
        continue
    m = b.parse_san(t)
    P.append((b.fen(), m.uci(), b.san(m)))
    b.push(m)
assert b.fen() == "6k1/p3P2p/1p3Q2/3p3K/2pP2P1/1nP5/7P/4q3 b - - 2 41"


def ply(n, white=True):
    return 2 * (n - 1) + (0 if white else 1)


fenb = lambda n, w=True: P[ply(n, w)][0]
uci = lambda n, w=True: P[ply(n, w)][1]


def line(a, b_, says={}):
    out = []
    for i in range(a, b_ + 1):
        d = {"move": P[i][1]}
        if i in says:
            d["say"] = says[i]
        out.append(d)
    return out


SRC = "Botvinnik v Capablanca, AVRO tournament, Rotterdam, round 11, 22 November 1938"


def pos(i, n):
    return {"id": f"PFGbotvinnikcapablanca-{i}", "fen": fenb(n), "family": "FAM-FG-BOTVINNIK-CAPABLANCA",
            "provenance": {"kind": "game", "ref": f"{SRC}; position before White's move {n} ({P[ply(n)][2]}); move record identical in Wikipedia 'Botvinnik versus Capablanca, AVRO 1938' and in Matthew Sadler's page matthewsadler.me.uk/?p=6671 (see lesson sources); every move replayed with python-chess; position generated by replaying the record", "licence": "facts (game moves)"}}


